root.command:

IF OBJECT_ID(N'dbo.OrdersTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.OrdersTbl', N'WalkInAreaID') IS NULL
    ALTER TABLE dbo.OrdersTbl ADD WalkInAreaID INT NULL;
IF OBJECT_ID(N'dbo.OrdersTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.OrdersTbl', N'WalkInLatitude') IS NULL
    ALTER TABLE dbo.OrdersTbl ADD WalkInLatitude DECIMAL(10, 6) NULL;
IF OBJECT_ID(N'dbo.OrdersTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.OrdersTbl', N'WalkInLongitude') IS NULL
    ALTER TABLE dbo.OrdersTbl ADD WalkInLongitude DECIMAL(10, 6) NULL;
